use agmp_native_protocol::*;use agmp_native_runtime::NativeRuntime;use clap::Parser;use serde_json::{json,Value};use std::{io::{self,BufRead,Write},path::PathBuf};
#[derive(Parser)]struct Args{#[arg(long)]root:PathBuf,#[arg(long)]managed_root:PathBuf}
fn main()->anyhow::Result<()>{let a=Args::parse();let runtime=NativeRuntime::new(a.root,a.managed_root)?;for line in io::stdin().lock().lines(){let line=line?;if line.trim().is_empty(){continue}let req:JsonRpcRequest=serde_json::from_str(&line)?;let result=dispatch(&runtime,&req);let resp=match result{Ok(v)=>JsonRpcResponse{jsonrpc:"2.0".into(),id:req.id,result:Some(v),error:None},Err(e)=>JsonRpcResponse{jsonrpc:"2.0".into(),id:req.id,result:None,error:Some(JsonRpcError{code:-32000,message:e.to_string()})}};println!("{}",serde_json::to_string(&resp)?);io::stdout().flush()?}Ok(())}
fn dispatch(r:&NativeRuntime,q:&JsonRpcRequest)->anyhow::Result<Value>{Ok(match q.method.as_str(){"runtime/status"=>serde_json::to_value(r.status())?,"capability/issue"=>serde_json::to_value(r.issue(serde_json::from_value(q.params.clone())?)?)?,"fs/list"=>r.list(q.params.get("path").and_then(Value::as_str).unwrap_or("."))?,"fs/readText"=>r.read_text(q.params.get("path").and_then(Value::as_str).unwrap_or_default())?,"fs/createDir"=>{r.create_dir(serde_json::from_value(q.params.clone())?)?;json!({"ok":true})},"fs/writeText"=>{r.write_text(serde_json::from_value(q.params.clone())?)?;json!({"ok":true})},"jobs/start"=>serde_json::to_value(r.start_job(serde_json::from_value(q.params.clone())?)?)?,"jobs/get"=>serde_json::to_value(r.job_get(q.params.get("id").and_then(Value::as_str).unwrap_or_default())?)?,"jobs/output"=>r.job_output(q.params.get("id").and_then(Value::as_str).unwrap_or_default(),q.params.get("after").and_then(Value::as_u64).unwrap_or(0),q.params.get("limit").and_then(Value::as_u64).unwrap_or(200) as usize)?,"environment/javaInspect"=>serde_json::to_value(r.java_inspect())?,"environment/javaEnsure"=>serde_json::to_value(r.java_ensure(serde_json::from_value(q.params.clone())?)?)?,"network/portAvailable"=>r.port_available(q.params.get("host").and_then(Value::as_str).unwrap_or("127.0.0.1"),q.params.get("port").and_then(Value::as_u64).unwrap_or(25565) as u16),"network/downloadVerified"=>r.download(serde_json::from_value(q.params.clone())?)?,"minecraft/ping"=>serde_json::to_value(r.mc_ping(q.params.get("host").and_then(Value::as_str).unwrap_or("127.0.0.1"),q.params.get("port").and_then(Value::as_u64).unwrap_or(25565) as u16,q.params.get("timeoutMs").and_then(Value::as_u64).unwrap_or(5000))?)?,other=>anyhow::bail!("unknown method: {other}")})}
